import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); String s = br.readLine(); String tStr = br.readLine(); int countS = 0; int countT = 0; for (int i = 0; i < n; i++) { if (s.charAt(i) == '1') countS++; if (tStr.charAt(i) == '1') countT++; } if (countS % 2 == countT % 2) { out.println("YES"); } else { out.println("NO"); } } out.flush(); out.close(); } }